function loadLazyYouTube(e){const r=e.dataset.videoId,o=e.dataset.videoTitle||"V\xEDdeo";if(!r)return;const t=document.createElement("iframe");t.src=`https://www.youtube-nocookie.com/embed/${r}?autoplay=1`,t.title=o,t.allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share; fullscreen",t.referrerPolicy="strict-origin-when-cross-origin",t.loading="lazy",t.style.border="0",e.replaceChildren(t),e.classList.remove("youtube-lazy"),e.removeAttribute("role"),e.removeAttribute("tabindex"),e.removeAttribute("aria-label")}document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".youtube-lazy").forEach(e=>{e.addEventListener("click",()=>loadLazyYouTube(e)),e.addEventListener("keydown",r=>{(r.key==="Enter"||r.key===" ")&&(r.preventDefault(),loadLazyYouTube(e))})})});
